ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
	items: payload.productos map (value, index) -> {
        idItem: value.id,
        parentId: value.idRaiz,
        provisioningDate: payload.fechaProcesamiento,
        listaConfiguraciones: value.parametros map (val, ind) ->{
            parametros: {
                atributo: val.nombre,
                valor: val.valor
            }
        }

    }
}
